// Dice si un punto cae dentro del poligono de la zona.
function puntoEnZona(lat, lon, zona) {
  const b = zona.bbox;
  if (lat < b[0] || lat > b[2] || lon < b[1] || lon > b[3]) return false;
  let dentro = false;
  const a = zona.anillo;
  for (let i = 0, j = a.length - 1; i < a.length; j = i++) {
    const yi = a[i][0], xi = a[i][1];
    const yj = a[j][0], xj = a[j][1];
    if ((yi > lat) !== (yj > lat)) {
      if (lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) dentro = !dentro;
    }
  }
  return dentro;
}

// Busca el corregimiento que contiene el punto. Devuelve null si no esta en el municipio.
function zonaDesdeGps(lat, lon) {
  for (const z of ZONAS) {
    if (puntoEnZona(lat, lon, z)) return z;
  }
  return null;
}

// Distancia en metros de un punto al borde de la zona (aproximada, para avisos).
function distanciaAlBorde(lat, lon, zona) {
  let min = Infinity;
  const a = zona.anillo;
  for (let i = 0, j = a.length - 1; i < a.length; j = i++) {
    const d = distSegmento(lat, lon, a[j], a[i]);
    if (d < min) min = d;
  }
  return min;
}

function distSegmento(px, py, a, b) {
  const dy = (b[0] - a[0]) * 111320;
  const dx = (b[1] - a[1]) * 111320 * Math.cos((a[0] * Math.PI) / 180);
  const ddx = (px - a[0]) * 111320;
  const ddy = (px === px ? (py - a[1]) * 111320 : 0);
  if (ddx === 0 && ddy === 0) return 0;
  const L2 = dx * dx + dy * dy;
  let t = L2 === 0 ? 0 : (ddx * dx + ddy * dy) / L2;
  t = Math.max(0, Math.min(1, t));
  const cx = a[0] + t * (b[0] - a[0]);
  const cy = a[1] + t * (b[1] - a[1]);
  const ax = (px - cx) * 111320;
  const ay = (py - cy) * 111320;
  return Math.sqrt(ax * ax + ay * ay);
}
